-- ============================================================
-- Pokefifa - exhaustive schema bootstrap + Gen1 species seed
-- ============================================================

CREATE EXTENSION IF NOT EXISTS pgcrypto;

DO
$$
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'UserRole') THEN
            CREATE TYPE "UserRole" AS ENUM ('USER', 'ADMIN');
        END IF;
        IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'BattleMode') THEN
            CREATE TYPE "BattleMode" AS ENUM ('CASUAL', 'RANKED', 'AI');
        END IF;
        IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'BattleResult') THEN
            CREATE TYPE "BattleResult" AS ENUM ('WIN', 'LOSS', 'DRAW');
        END IF;
        IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'TeamStatus') THEN
            CREATE TYPE "TeamStatus" AS ENUM ('ACTIVE', 'ARCHIVED');
        END IF;
        IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'CreatureRarity') THEN
            CREATE TYPE "CreatureRarity" AS ENUM ('COMMON', 'RARE', 'EPIC', 'LEGENDARY', 'MYTHIC');
        END IF;
        IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'InventoryItemType') THEN
            CREATE TYPE "InventoryItemType" AS ENUM ('ITEM', 'TM', 'EVO_MATERIAL', 'PACK', 'CURRENCY');
        END IF;
        IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'PackType') THEN
            CREATE TYPE "PackType" AS ENUM ('BRONZE', 'SILVER', 'ELITE', 'EVENT');
        END IF;
        IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'PackSource') THEN
            CREATE TYPE "PackSource" AS ENUM ('SHOP', 'REWARD', 'GIFT', 'ADMIN');
        END IF;
        IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'CurrencyType') THEN
            CREATE TYPE "CurrencyType" AS ENUM ('COINS', 'GEMS', 'SHARDS');
        END IF;
        IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'TransactionType') THEN
            CREATE TYPE "TransactionType" AS ENUM (
                'BATTLE_REWARD',
                'PACK_PURCHASE',
                'PACK_OPEN',
                'QUEST_REWARD',
                'ADMIN_GRANT',
                'DUPLICATE_CONVERT',
                'CRAFT'
                );
        END IF;
    END
$$;

CREATE TABLE IF NOT EXISTS "User"
(
    "id"           TEXT PRIMARY KEY     DEFAULT gen_random_uuid()::text,
    "email"        TEXT        NOT NULL UNIQUE,
    "username"     TEXT        NOT NULL UNIQUE,
    "passwordHash" TEXT        NOT NULL,
    "role"         "UserRole"  NOT NULL DEFAULT 'USER',
    "coins"        INTEGER     NOT NULL DEFAULT 0,
    "gems"         INTEGER     NOT NULL DEFAULT 0,
    "shards"       INTEGER     NOT NULL DEFAULT 0,
    "rating"       INTEGER     NOT NULL DEFAULT 1000,
    "level"        INTEGER     NOT NULL DEFAULT 1,
    "xp"           INTEGER     NOT NULL DEFAULT 0,
    "createdAt"    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "updatedAt"    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS "CreatureSpecies"
(
    "id"            TEXT PRIMARY KEY          DEFAULT gen_random_uuid()::text,
    "slug"          TEXT             NOT NULL UNIQUE,
    "name"          TEXT             NOT NULL,
    "rarity"        "CreatureRarity" NOT NULL,
    "primaryType"   TEXT             NOT NULL,
    "secondaryType" TEXT,
    "baseHp"        INTEGER          NOT NULL,
    "baseAttack"    INTEGER          NOT NULL,
    "baseDefense"   INTEGER          NOT NULL,
    "baseSpAttack"  INTEGER          NOT NULL,
    "baseSpDefense" INTEGER          NOT NULL,
    "baseSpeed"     INTEGER          NOT NULL,
    "abilityName"   TEXT,
    "description"   TEXT,
    "createdAt"     TIMESTAMPTZ      NOT NULL DEFAULT NOW(),
    "updatedAt"     TIMESTAMPTZ      NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS "Move"
(
    "id"             TEXT PRIMARY KEY     DEFAULT gen_random_uuid()::text,
    "slug"           TEXT        NOT NULL UNIQUE,
    "name"           TEXT        NOT NULL,
    "type"           TEXT        NOT NULL,
    "power"          INTEGER,
    "accuracy"       INTEGER,
    "pp"             INTEGER,
    "isTmCompatible" BOOLEAN     NOT NULL DEFAULT FALSE,
    "description"    TEXT,
    "createdAt"      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "updatedAt"      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS "SpeciesMove"
(
    "id"          TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    "speciesId"   TEXT    NOT NULL,
    "moveId"      TEXT    NOT NULL,
    "unlockLevel" INTEGER NOT NULL DEFAULT 1,
    "isDefault"   BOOLEAN NOT NULL DEFAULT FALSE,
    CONSTRAINT "SpeciesMove_speciesId_fkey" FOREIGN KEY ("speciesId") REFERENCES "CreatureSpecies" ("id") ON DELETE CASCADE,
    CONSTRAINT "SpeciesMove_moveId_fkey" FOREIGN KEY ("moveId") REFERENCES "Move" ("id") ON DELETE CASCADE,
    CONSTRAINT "SpeciesMove_speciesId_moveId_key" UNIQUE ("speciesId", "moveId")
);

CREATE TABLE IF NOT EXISTS "Team"
(
    "id"        TEXT PRIMARY KEY      DEFAULT gen_random_uuid()::text,
    "userId"    TEXT         NOT NULL,
    "name"      TEXT         NOT NULL,
    "status"    "TeamStatus" NOT NULL DEFAULT 'ACTIVE',
    "isDefault" BOOLEAN      NOT NULL DEFAULT FALSE,
    "createdAt" TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    "updatedAt" TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    CONSTRAINT "Team_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "UserCreature"
(
    "id"                 TEXT PRIMARY KEY     DEFAULT gen_random_uuid()::text,
    "userId"             TEXT        NOT NULL,
    "speciesId"          TEXT        NOT NULL,
    "nickname"           TEXT,
    "level"              INTEGER     NOT NULL DEFAULT 1,
    "xp"                 INTEGER     NOT NULL DEFAULT 0,
    "ivHp"               INTEGER     NOT NULL DEFAULT 0,
    "ivAttack"           INTEGER     NOT NULL DEFAULT 0,
    "ivDefense"          INTEGER     NOT NULL DEFAULT 0,
    "ivSpAttack"         INTEGER     NOT NULL DEFAULT 0,
    "ivSpDefense"        INTEGER     NOT NULL DEFAULT 0,
    "ivSpeed"            INTEGER     NOT NULL DEFAULT 0,
    "isFavorite"         BOOLEAN     NOT NULL DEFAULT FALSE,
    "isLocked"           BOOLEAN     NOT NULL DEFAULT FALSE,
    "heldItemInstanceId" TEXT,
    "createdAt"          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "updatedAt"          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT "UserCreature_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE,
    CONSTRAINT "UserCreature_speciesId_fkey" FOREIGN KEY ("speciesId") REFERENCES "CreatureSpecies" ("id")
);

CREATE TABLE IF NOT EXISTS "UserCreatureMove"
(
    "id"             TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    "userCreatureId" TEXT    NOT NULL,
    "moveId"         TEXT    NOT NULL,
    "slot"           INTEGER NOT NULL,
    CONSTRAINT "UserCreatureMove_userCreatureId_fkey" FOREIGN KEY ("userCreatureId") REFERENCES "UserCreature" ("id") ON DELETE CASCADE,
    CONSTRAINT "UserCreatureMove_moveId_fkey" FOREIGN KEY ("moveId") REFERENCES "Move" ("id"),
    CONSTRAINT "UserCreatureMove_userCreatureId_slot_key" UNIQUE ("userCreatureId", "slot")
);

CREATE TABLE IF NOT EXISTS "TeamSlot"
(
    "id"             TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    "teamId"         TEXT    NOT NULL,
    "userCreatureId" TEXT    NOT NULL,
    "slot"           INTEGER NOT NULL,
    CONSTRAINT "TeamSlot_teamId_fkey" FOREIGN KEY ("teamId") REFERENCES "Team" ("id") ON DELETE CASCADE,
    CONSTRAINT "TeamSlot_userCreatureId_fkey" FOREIGN KEY ("userCreatureId") REFERENCES "UserCreature" ("id") ON DELETE CASCADE,
    CONSTRAINT "TeamSlot_teamId_slot_key" UNIQUE ("teamId", "slot"),
    CONSTRAINT "TeamSlot_teamId_userCreatureId_key" UNIQUE ("teamId", "userCreatureId")
);

CREATE TABLE IF NOT EXISTS "InventoryItem"
(
    "id"          TEXT PRIMARY KEY             DEFAULT gen_random_uuid()::text,
    "slug"        TEXT                NOT NULL UNIQUE,
    "name"        TEXT                NOT NULL,
    "type"        "InventoryItemType" NOT NULL,
    "description" TEXT,
    "tmMoveId"    TEXT,
    "createdAt"   TIMESTAMPTZ         NOT NULL DEFAULT NOW(),
    "updatedAt"   TIMESTAMPTZ         NOT NULL DEFAULT NOW(),
    CONSTRAINT "InventoryItem_tmMoveId_fkey" FOREIGN KEY ("tmMoveId") REFERENCES "Move" ("id")
);

CREATE TABLE IF NOT EXISTS "UserInventoryItem"
(
    "id"        TEXT PRIMARY KEY     DEFAULT gen_random_uuid()::text,
    "userId"    TEXT        NOT NULL,
    "itemId"    TEXT        NOT NULL,
    "quantity"  INTEGER     NOT NULL DEFAULT 0,
    "createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT "UserInventoryItem_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE,
    CONSTRAINT "UserInventoryItem_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "InventoryItem" ("id"),
    CONSTRAINT "UserInventoryItem_userId_itemId_key" UNIQUE ("userId", "itemId")
);

CREATE TABLE IF NOT EXISTS "PackDefinition"
(
    "id"          TEXT PRIMARY KEY     DEFAULT gen_random_uuid()::text,
    "slug"        TEXT        NOT NULL UNIQUE,
    "name"        TEXT        NOT NULL,
    "type"        "PackType"  NOT NULL,
    "coinPrice"   INTEGER,
    "gemPrice"    INTEGER,
    "isActive"    BOOLEAN     NOT NULL DEFAULT TRUE,
    "description" TEXT,
    "createdAt"   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "updatedAt"   TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS "PackDropCreature"
(
    "id"               TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    "packDefinitionId" TEXT    NOT NULL,
    "speciesId"        TEXT    NOT NULL,
    "weight"           INTEGER NOT NULL,
    CONSTRAINT "PackDropCreature_packDefinitionId_fkey" FOREIGN KEY ("packDefinitionId") REFERENCES "PackDefinition" ("id") ON DELETE CASCADE,
    CONSTRAINT "PackDropCreature_speciesId_fkey" FOREIGN KEY ("speciesId") REFERENCES "CreatureSpecies" ("id"),
    CONSTRAINT "PackDropCreature_packDefinitionId_speciesId_key" UNIQUE ("packDefinitionId", "speciesId")
);

CREATE TABLE IF NOT EXISTS "PackDropItem"
(
    "id"               TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    "packDefinitionId" TEXT    NOT NULL,
    "itemId"           TEXT    NOT NULL,
    "quantityMin"      INTEGER NOT NULL DEFAULT 1,
    "quantityMax"      INTEGER NOT NULL DEFAULT 1,
    "weight"           INTEGER NOT NULL,
    CONSTRAINT "PackDropItem_packDefinitionId_fkey" FOREIGN KEY ("packDefinitionId") REFERENCES "PackDefinition" ("id") ON DELETE CASCADE,
    CONSTRAINT "PackDropItem_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "InventoryItem" ("id"),
    CONSTRAINT "PackDropItem_packDefinitionId_itemId_key" UNIQUE ("packDefinitionId", "itemId")
);

CREATE TABLE IF NOT EXISTS "UserPack"
(
    "id"               TEXT PRIMARY KEY      DEFAULT gen_random_uuid()::text,
    "userId"           TEXT         NOT NULL,
    "packDefinitionId" TEXT         NOT NULL,
    "source"           "PackSource" NOT NULL DEFAULT 'SHOP',
    "openedAt"         TIMESTAMPTZ,
    "createdAt"        TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    CONSTRAINT "UserPack_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE,
    CONSTRAINT "UserPack_packDefinitionId_fkey" FOREIGN KEY ("packDefinitionId") REFERENCES "PackDefinition" ("id")
);

CREATE TABLE IF NOT EXISTS "PackOpeningReward"
(
    "id"         TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    "userPackId" TEXT    NOT NULL,
    "rewardType" TEXT    NOT NULL,
    "speciesId"  TEXT,
    "itemId"     TEXT,
    "quantity"   INTEGER NOT NULL DEFAULT 1,
    CONSTRAINT "PackOpeningReward_userPackId_fkey" FOREIGN KEY ("userPackId") REFERENCES "UserPack" ("id") ON DELETE CASCADE,
    CONSTRAINT "PackOpeningReward_speciesId_fkey" FOREIGN KEY ("speciesId") REFERENCES "CreatureSpecies" ("id"),
    CONSTRAINT "PackOpeningReward_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "InventoryItem" ("id")
);

CREATE TABLE IF NOT EXISTS "Battle"
(
    "id"                  TEXT PRIMARY KEY      DEFAULT gen_random_uuid()::text,
    "mode"                "BattleMode" NOT NULL,
    "playerAId"           TEXT         NOT NULL,
    "playerBId"           TEXT,
    "playerATeamId"       TEXT         NOT NULL,
    "playerBTeamId"       TEXT,
    "winnerUserId"        TEXT,
    "resultForA"          "BattleResult",
    "resultForB"          "BattleResult",
    "playerARatingBefore" INTEGER,
    "playerARatingAfter"  INTEGER,
    "playerBRatingBefore" INTEGER,
    "playerBRatingAfter"  INTEGER,
    "coinsAwardedA"       INTEGER      NOT NULL DEFAULT 0,
    "coinsAwardedB"       INTEGER      NOT NULL DEFAULT 0,
    "battleLogJson"       JSONB,
    "createdAt"           TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    "finishedAt"          TIMESTAMPTZ,
    CONSTRAINT "Battle_playerAId_fkey" FOREIGN KEY ("playerAId") REFERENCES "User" ("id") ON DELETE CASCADE,
    CONSTRAINT "Battle_playerBId_fkey" FOREIGN KEY ("playerBId") REFERENCES "User" ("id"),
    CONSTRAINT "Battle_playerATeamId_fkey" FOREIGN KEY ("playerATeamId") REFERENCES "Team" ("id"),
    CONSTRAINT "Battle_playerBTeamId_fkey" FOREIGN KEY ("playerBTeamId") REFERENCES "Team" ("id")
);

CREATE TABLE IF NOT EXISTS "CurrencyTransaction"
(
    "id"              TEXT PRIMARY KEY           DEFAULT gen_random_uuid()::text,
    "userId"          TEXT              NOT NULL,
    "currencyType"    "CurrencyType"    NOT NULL,
    "amount"          INTEGER           NOT NULL,
    "transactionType" "TransactionType" NOT NULL,
    "referenceId"     TEXT,
    "metadata"        JSONB,
    "createdAt"       TIMESTAMPTZ       NOT NULL DEFAULT NOW(),
    CONSTRAINT "CurrencyTransaction_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE
);

