CREATE INDEX IF NOT EXISTS "UserInventoryItem_userId_idx" ON "UserInventoryItem" ("userId");
CREATE INDEX IF NOT EXISTS "UserInventoryItem_itemId_idx" ON "UserInventoryItem" ("itemId");
CREATE INDEX IF NOT EXISTS "PackDefinition_type_idx" ON "PackDefinition" ("type");
CREATE INDEX IF NOT EXISTS "PackDefinition_isActive_idx" ON "PackDefinition" ("isActive");
CREATE INDEX IF NOT EXISTS "PackDropCreature_packDefinitionId_idx" ON "PackDropCreature" ("packDefinitionId");
CREATE INDEX IF NOT EXISTS "PackDropCreature_speciesId_idx" ON "PackDropCreature" ("speciesId");
CREATE INDEX IF NOT EXISTS "PackDropItem_packDefinitionId_idx" ON "PackDropItem" ("packDefinitionId");
CREATE INDEX IF NOT EXISTS "PackDropItem_itemId_idx" ON "PackDropItem" ("itemId");
