CREATE INDEX IF NOT EXISTS "UserPack_packDefinitionId_idx" ON "UserPack" ("packDefinitionId");
CREATE INDEX IF NOT EXISTS "UserPack_openedAt_idx" ON "UserPack" ("openedAt");
CREATE INDEX IF NOT EXISTS "PackOpeningReward_userPackId_idx" ON "PackOpeningReward" ("userPackId");
CREATE INDEX IF NOT EXISTS "PackOpeningReward_speciesId_idx" ON "PackOpeningReward" ("speciesId");
CREATE INDEX IF NOT EXISTS "PackOpeningReward_itemId_idx" ON "PackOpeningReward" ("itemId");
CREATE INDEX IF NOT EXISTS "Battle_playerAId_idx" ON "Battle" ("playerAId");
CREATE INDEX IF NOT EXISTS "Battle_playerBId_idx" ON "Battle" ("playerBId");
