INSERT
INTO "SpeciesMove" ("id", "speciesId", "moveId", "unlockLevel", "isDefault")
SELECT gen_random_uuid()::text,
       cs."id",
       m."id",
       seed.unlock_level,
       seed.is_default
FROM seed
         JOIN "CreatureSpecies" cs ON cs."slug" = seed.species_slug
         JOIN "Move" m ON m."slug" = seed.move_slug
ON CONFLICT ("speciesId","moveId") DO UPDATE SET "unlockLevel" = EXCLUDED."unlockLevel",
                                                 "isDefault"   = EXCLUDED."isDefault";


