INSERT
INTO "InventoryItem" ("id", "slug", "name", "type", "description", "tmMoveId", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text,
       seed.slug,
       seed.name,
       seed.type::"InventoryItemType",
       seed.description,
       m."id",
       NOW(),
       NOW()
FROM seed
         LEFT JOIN "Move" m ON m."slug" = seed.tm_move_slug
ON CONFLICT ("slug") DO UPDATE SET "name"        = EXCLUDED."name",
                                   "type"        = EXCLUDED."type",
                                   "description" = EXCLUDED."description",
                                   "tmMoveId"    = EXCLUDED."tmMoveId",
                                   "updatedAt"   = NOW();


