FROM seed
         JOIN "PackDefinition" p ON p."slug" = seed.pack_slug
         JOIN "CreatureSpecies" cs ON cs."slug" = seed.species_slug
ON CONFLICT ("packDefinitionId","speciesId") DO UPDATE SET "weight" = EXCLUDED."weight";


